/**
 * Helper to get optimized WebP variants generated by sharp.
 * If the image is a brand or hoodie asset, returns the -480w or -800w WebP variant.
 */
export function getOptimizedSrc(src: string, width: 480 | 800 = 800): string {
  if (!src || typeof src !== "string") return src;
  if (!src.startsWith("/brand/") && !src.startsWith("/hoodies/")) return src;

  // Don't modify if already an optimized variant
  if (src.includes("-480w.webp") || src.includes("-800w.webp")) return src;

  const dotIdx = src.lastIndexOf(".");
  if (dotIdx === -1) return src;

  const basePath = src.slice(0, dotIdx);
  return `${basePath}-${width}w.webp`;
}

/**
 * Returns a standard HTML srcset string with 480w and 800w variants and the original as 1200w.
 */
export function getOptimizedSrcSet(src: string): string {
  if (!src || typeof src !== "string") return "";
  if (!src.startsWith("/brand/") && !src.startsWith("/hoodies/")) return "";

  const dotIdx = src.lastIndexOf(".");
  if (dotIdx === -1) return "";

  const basePath = src.slice(0, dotIdx);
  return `${basePath}-480w.webp 480w, ${basePath}-800w.webp 800w, ${src} 1200w`;
}
